namespace SmsPanel.Api.Domain;

public sealed class Person { public long Id { get; set; } public required string NationalCode { get; set; } public required string FirstName { get; set; } public required string LastName { get; set; } public required string Mobile { get; set; } public string? CurrentIban { get; set; } public long? SourceImportBatchId { get; set; } }
public sealed class Campaign { public long Id { get; set; } public required string Name { get; set; } public required string MessageTemplate { get; set; } public bool ConfirmationEnabled { get; set; } public string? ConfirmationTemplate { get; set; } public bool InvalidReplyEnabled { get; set; } public string? InvalidReplyTemplate { get; set; } public CampaignStatus Status { get; set; } public DateTimeOffset StartsAtUtc { get; set; } public DateTimeOffset? EndsAtUtc { get; set; } }
public sealed class OutboundMessage { public long Id { get; set; } public long CampaignId { get; set; } public long PersonId { get; set; } public required string RenderedText { get; set; } public OutboundStatus Status { get; set; } public int AttemptCount { get; set; } public string? ProviderReference { get; set; } public string? LastError { get; set; } public DateTimeOffset? SentAtUtc { get; set; } }
public sealed class InboundMessage { public long Id { get; set; } public required string Provider { get; set; } public required string ProviderMessageId { get; set; } public required string SenderMobile { get; set; } public string? ReceiverNumber { get; set; } public required string RawText { get; set; } public DateTimeOffset ReceivedAtUtc { get; set; } public DateTimeOffset FetchedAtUtc { get; set; } public ProcessingStatus ProcessingStatus { get; set; } public string? LastError { get; set; } public long? MatchedPersonId { get; set; } }
public sealed class SecondaryBankAccount { public long Id { get; set; } public long PersonId { get; set; } public long CampaignId { get; set; } public long InboundMessageId { get; set; } public required string Iban { get; set; } public bool? OwnershipVerified { get; set; } public DateTimeOffset ReceivedAtUtc { get; set; } }
public sealed class ReconciliationIssue { public long Id { get; set; } public long? CampaignId { get; set; } public long InboundMessageId { get; set; } public required string SenderMobile { get; set; } public string? ExtractedIban { get; set; } public IssueType IssueType { get; set; } public IssueStatus Status { get; set; } = IssueStatus.Open; public string? ResolutionNote { get; set; } public DateTimeOffset CreatedAtUtc { get; set; } = DateTimeOffset.UtcNow; public DateTimeOffset? ResolvedAtUtc { get; set; } }
public sealed class ReconciliationIssueMessage { public long Id { get; set; } public long ReconciliationIssueId { get; set; } public required string Text { get; set; } public OutboundStatus Status { get; set; } public string? ProviderReference { get; set; } public string? LastError { get; set; } public required string SentBy { get; set; } public DateTimeOffset CreatedAtUtc { get; set; } = DateTimeOffset.UtcNow; public DateTimeOffset? SentAtUtc { get; set; } }
public sealed class MerchantImportBatch { public long Id { get; set; } public required string OriginalFileName { get; set; } public required string StoredFileName { get; set; } public required string FileHash { get; set; } public ImportStatus Status { get; set; } public int TotalRows { get; set; } public int ProcessedRows { get; set; } public int InsertedRows { get; set; } public int DuplicateRows { get; set; } public int InvalidRows { get; set; } public string? CurrentStage { get; set; } public string? LastError { get; set; } public DateTimeOffset CreatedAtUtc { get; set; } = DateTimeOffset.UtcNow; public DateTimeOffset? StartedAtUtc { get; set; } public DateTimeOffset? CompletedAtUtc { get; set; } public DateTimeOffset? InvalidatedAtUtc { get; set; } }
public sealed class Merchant { public long Id { get; set; } public long ImportBatchId { get; set; } public required string TerminalNumber { get; set; } public required string NationalId { get; set; } public required string MerchantName { get; set; } public string? Mobile { get; set; } public string? Status { get; set; } public string? CurrentIban { get; set; } public string? Bank { get; set; } public string? Agency { get; set; } public long? PersonId { get; set; } public Person? Person { get; set; } }
public sealed class AppUser { public long Id { get; set; } public required string Username { get; set; } public required string DisplayName { get; set; } public required string PasswordHash { get; set; } public bool IsAdmin { get; set; } public bool IsActive { get; set; } = true; public DateTimeOffset CreatedAtUtc { get; set; } = DateTimeOffset.UtcNow; public DateTimeOffset? LastLoginAtUtc { get; set; } }
public enum CampaignStatus { Draft, Active, Closed, Suspended }
public enum OutboundStatus { Pending, Processing, Sent, Failed }
public enum ProcessingStatus { Pending, Processed, ReconciliationRequired, Failed, ResolvedManually }
public enum IssueStatus { Open, Resolved, Rejected }
public enum IssueType { MobileNotFound, MobileMatchesMultiplePeople, NoIbanFound, InvalidIban, MultipleIbansFound, IbanEqualsCurrentIban, IbanUsedByAnotherPerson, MultipleDifferentReplies, RequestNotActive, RequestAmbiguous, IncompleteIban, BankCardNumberReceived, AccountHolderNameMismatch }
public enum CampaignRecipientStatus { Successful, NoReply, NoIbanFound, InvalidIban, MultipleIbansFound, IbanEqualsCurrentIban, IbanUsedByAnotherPerson, MultipleDifferentReplies, RequestNotActive, RequestAmbiguous, IncompleteIban, BankCardNumberReceived, AccountHolderNameMismatch }
public enum ImportStatus { Queued, Validating, Importing, Completed, Failed, Invalidated }
